class Solution:
    def minMaxSubarraySum(self, nums, k):
        n = len(nums)

        def S(m, r):
            # sum_{t=1}^{m} min(r, t)
            if m <= r:
                return m * (m + 1) // 2
            return r * (r + 1) // 2 + (m - r) * r

        def calc(is_min):
            # prev: previous index that stops nums[i]; next_: next index that stops nums[i]
            prev = [-1] * n
            next_ = [n] * n
            stack = []
            for i in range(n):
                while stack and ((nums[stack[-1]] > nums[i]) if is_min else (nums[stack[-1]] < nums[i])):
                    stack.pop()
                prev[i] = stack[-1] if stack else -1
                stack.append(i)
            stack = []
            for i in range(n - 1, -1, -1):
                while stack and ((nums[stack[-1]] >= nums[i]) if is_min else (nums[stack[-1]] <= nums[i])):
                    stack.pop()
                next_[i] = stack[-1] if stack else n
                stack.append(i)

            total = 0
            for i in range(n):
                l = i - prev[i]      # choices for the left endpoint
                r = next_[i] - i     # choices for the right endpoint
                a = min(l, k)
                # sum over x = 1..a of min(r, k - x + 1)
                cnt = S(k, r) - S(k - a, r)
                total += nums[i] * cnt
            return total

        return calc(True) + calc(False)
